import java.io.*;import java.nio.file.*;
public class Main {static class Pass implements Serializable{private static final long serialVersionUID=1L;String id,name;transient String sessionToken;Pass(String i,String n,String t){id=i;name=n;sessionToken=t;}}public static void main(String[]a)throws Exception{Pass p=new Pass("P1","Mahesh","SECRET");try(ObjectOutputStream o=new ObjectOutputStream(Files.newOutputStream(Path.of("pass.ser")))){o.writeObject(p);}try(ObjectInputStream in=new ObjectInputStream(Files.newInputStream(Path.of("pass.ser")))){Pass q=(Pass)in.readObject();System.out.println(q.id+" "+q.name+" token="+q.sessionToken);}}}
